import React from "react";
import { View } from "react-native";
import { Form, FormItem, FormLabel, FormControl, FormDescription, FormMessage } from "@nativecn/ui/components/form";
import { Input } from "@nativecn/ui/components/input";
import { Button } from "@nativecn/ui/components/button";

export default function App() {
  const [email, setEmail] = React.useState("");
  const [error, setError] = React.useState("");

  const handleSubmit = () => {
    if (!email.includes("@")) {
      setError("Invalid email address.");
    } else {
      setError("");
      console.log("Submitted email:", email);
    }
  };

  return (
    <Form>
      <FormItem>
        <FormLabel error={!!error}>Email Address</FormLabel>
        <FormControl>
          <Input 
            value={email}
            onChangeText={setEmail}
            placeholder="name@example.com"
            error={!!error}
          />
        </FormControl>
        <FormDescription>
          We will never share your email address with anyone else.
        </FormDescription>
        <FormMessage>{error}</FormMessage>
      </FormItem>
      <Button onPress={handleSubmit}>
        <Button.Text>Submit</Button.Text>
      </Button>
    </Form>
  );
}
